    @property
    def hidden(self): return bool(self.first_tag('hidden'))

    def first_tag(self, name):
        values=self.tags.get(name, [])
        return values[0] if values else None

def _date(token):
    if not _VALID_DATE.fullmatch(token): return False
    try: date.fromisoformat(token); return True
    except ValueError: return False

def parse_todo(line: str, id: int = 1) -> Todo:
    """Parse one todo.txt line. Invalid date-like fields remain in subject."""
    raw=line.rstrip("\r\n")
