The matcher accepts mappings or objects. Standard record attributes are
recognized by their common names; unknown fields are read from a tags mapping.
"""
import re
from datetime import date, timedelta

ALIASES = {
    'ID': 'id', 'priority': 'priority', 'pri': 'priority', 'done': 'done',
    'subject': 'subject', 'subj': 'subject', 'project': 'project', 'prj': 'project', '+': 'project',
    'context': 'context', 'ctx': 'context', '@': 'context', 'hashtag': 'hashtag', '#': 'hashtag',
    'completed': 'completed', 'created': 'created', 'create': 'created',
    'due': 'due', 'rec': 'rec', 'time': 'time',
}

def _get(todo, name):
    tag_only = name.startswith('tag:')
    if tag_only: name = name[4:]
    # Parser Todo dataclasses expose project/context/hashtag values as lists.
    aliases = {'project': 'projects', 'context': 'contexts', 'hashtag': 'hashtags', 'priority': 'pri', 'completed': 'finished'}
    builtin = not tag_only and name in set(ALIASES.values()) | set(ALIASES.keys())
    if isinstance(todo, dict):
        tags = todo.get('tags', {})
        if builtin:
            if name in todo: return todo[name]
            alt = aliases.get(name)
            if alt in todo: return todo[alt]
        if isinstance(tags, dict) and name in tags: return tags[name]
    else:
        tags = getattr(todo, 'tags', {})
        if builtin:
            if hasattr(todo, name): return getattr(todo, name)
            alt = aliases.get(name)
            if alt and hasattr(todo, alt): return getattr(todo, alt)
        if isinstance(tags, dict) and name in tags: return tags[name]
    return None

def _values(v):
    if v is None or v == '': return []
    if isinstance(v, (list, tuple, set)): return list(v)
    if isinstance(v, bool): return [str(v).lower()]
    return [str(v)]

def _dateval(s):
    if not s:
        return None
    try:
        from datefilters import date_value
        return date_value(s)
    except Exception:
        try:
            return date.fromisoformat(s)
        except Exception:
            return None

def _duration_seconds(value):
    """Parse TTDL compact interval strings into seconds."""
    mlist = re.findall(r"(\d+)([wdhms])", value.lower())
    if not mlist or ''.join(n+u for n,u in mlist) != value.lower(): return None
    scale={'w':604800,'d':86400,'h':3600,'m':60,'s':1}
    return sum(int(n)*scale[u] for n,u in mlist)

def _size_bytes(value):
    m=re.fullmatch(r"(\d+(?:\.\d+)?)([kmgtpe]?i?b)?", value, re.I)
    if not m: return None
    suffix=(m.group(2) or '').lower()
    power={'':0,'b':0,'kb':1,'kib':1,'mb':2,'mib':2,'gb':3,'gib':3,'tb':4,'tib':4,'pb':5,'pib':5,'eb':6,'eib':6}.get(suffix)
    if power is None:return None
    return float(m.group(1))*(1024**power)

def _time_minutes(value):
    value=value.strip().lower()
    z=re.fullmatch(r"(\d{1,2})(?::?(\d{2}))?\s*(am|pm)?",value)
    if not z and re.fullmatch(r"\d{3,4}",value):
        z=re.fullmatch(r"(\d{1,2})(\d{2})",value)
    if not z:return None
    h=int(z.group(1)); m=int(z.group(2) or 0); ap=(z.group(3) or '').lower()
    if m>59 or h>23 or (ap and not 1<=h<=12):return None
    if ap:h=h%12+(12 if ap=='pm' else 0)
    return h*60+m

